-- Fictional fixtures in the disposable validation database only.
begin;
set local timezone='UTC';
create schema dining_test;
create function dining_test.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'ok - booking: %',label;end$$;
create function dining_test.fails(command text,code text,label text) returns void language plpgsql as $$begin begin execute command;exception when others then if sqlstate<>code then raise exception 'FAIL: % expected %, got %: %',label,code,sqlstate,sqlerrm;end if;raise notice 'ok - booking: % (refused)',label;return;end;raise exception 'FAIL: % was permitted',label;end$$;
grant usage on schema dining_test to anon,authenticated,service_role;grant execute on all functions in schema dining_test to anon,authenticated,service_role;
insert into auth.users(id,email) values('bc000000-0000-4000-8000-000000000001','dining-owner@example.test'),('bc000000-0000-4000-8000-000000000002','dining-other@example.test'),('bc000000-0000-4000-8000-000000000003','dining-member@example.test');
insert into public.organizations(id,name,slug) values('bc000000-0000-4000-8000-000000000011','Booking A','dining-a'),('bc000000-0000-4000-8000-000000000012','Booking B','dining-b');
insert into public.organization_members(organization_id,user_id,role,status) values('bc000000-0000-4000-8000-000000000011','bc000000-0000-4000-8000-000000000001','owner','active'),('bc000000-0000-4000-8000-000000000012','bc000000-0000-4000-8000-000000000002','owner','active'),('bc000000-0000-4000-8000-000000000011','bc000000-0000-4000-8000-000000000003','member','active');
insert into public.websites(id,organization_id,name,status,live_url) values('bc000000-0000-4000-8000-000000000021','bc000000-0000-4000-8000-000000000011','Booking A','live','https://dining-a.example.test'),('bc000000-0000-4000-8000-000000000022','bc000000-0000-4000-8000-000000000012','Booking B','live','https://dining-b.example.test');
insert into public.subscriptions(organization_id,website_id,plan_id,status,current_period_end) select organization_id,id,(select id from public.plans where code=case when w.name='Booking A' then 'care' else 'basic' end),'active',now()+interval '30 days' from public.websites w where id::text like 'bc%';
insert into public.website_contact_settings(website_id,organization_id,notification_email,allowed_origins,enabled) select id,organization_id,'owner@example.test',array[live_url],true from public.websites where id::text like 'bc%';

select set_config('request.jwt.claim.role','authenticated',true);select set_config('request.jwt.claim.sub','bc000000-0000-4000-8000-000000000001',true);set local role authenticated;
select public.save_booking_table('bc000000-0000-4000-8000-000000000021','{"id":"bc000000-0000-4000-8000-000000000031","name":"Two seats","active":true,"minParty":1,"maxParty":2}');
select public.save_booking_table('bc000000-0000-4000-8000-000000000021','{"id":"bc000000-0000-4000-8000-000000000032","name":"Four seats","active":true,"minParty":1,"maxParty":4}');
select public.save_booking_table('bc000000-0000-4000-8000-000000000021','{"id":"bc000000-0000-4000-8000-000000000033","name":"Six seats","active":true,"minParty":3,"maxParty":6}');
select public.save_booking_dining_hours('bc000000-0000-4000-8000-000000000021',(select jsonb_agg(jsonb_build_object('day',d,'start','11:00','end','22:00')) from generate_series(0,6)d));
select public.save_booking_service('bc000000-0000-4000-8000-000000000021','{"id":"bc000000-0000-4000-8000-000000000041","resourceId":null,"allocation":"table_pool","name":"Dining","description":"","duration":90,"bufferBefore":0,"bufferAfter":15,"mode":"instant","active":true}');
select public.save_booking_service('bc000000-0000-4000-8000-000000000021','{"id":"bc000000-0000-4000-8000-000000000042","resourceId":null,"allocation":"table_pool","name":"Dining request","description":"","duration":90,"bufferBefore":0,"bufferAfter":15,"mode":"approval","active":true}');
select dining_test.ok((select not enabled and not component_ready from public.booking_settings where website_id='bc000000-0000-4000-8000-000000000021'),'table setup never activates a website');
select dining_test.fails($q$select public.save_booking_table('bc000000-0000-4000-8000-000000000021','{"name":"Bad","active":true,"minParty":5,"maxParty":2}')$q$,'22023','invalid capacity refused');
select dining_test.fails($q$select public.save_booking_table('bc000000-0000-4000-8000-000000000022','{"name":"Forged","active":true,"minParty":1,"maxParty":2}')$q$,'42501','cross-tenant table setup refused');
select dining_test.fails($q$select vigil.booking_choose_resource(null,null,2,now(),90,0,0)$q$,'42501','allocator cannot bypass authorized RPCs');
reset role;update public.booking_settings set component_ready=true where website_id='bc000000-0000-4000-8000-000000000021';set local role authenticated;
select public.configure_bookings('bc000000-0000-4000-8000-000000000021','{"timeZone":"UTC","enabled":true,"acknowledgeAvailability":true,"minimumNotice":0,"horizonDays":180,"changeNotice":120}');
reset role;
create function dining_test.book(p_party integer,p_key integer,p_hour integer default 15,p_approval boolean default false) returns jsonb language sql as $$
 select public.create_public_booking('bc000000-0000-4000-8000-000000000021','https://dining-a.example.test',case when p_approval then 'bc000000-0000-4000-8000-000000000042'::uuid else 'bc000000-0000-4000-8000-000000000041'::uuid end,
 (current_date+3)+make_time(p_hour,0,0),('bc000000-0000-4000-8000-'||lpad(p_key::text,12,'0'))::uuid,repeat('a',64),repeat('b',64),'{"name":"Fictional diner","email":"diner@example.test"}','','',p_party)
$$;
grant execute on function dining_test.book(integer,integer,integer,boolean) to service_role;
select set_config('request.jwt.claim.role','service_role',true);set local role service_role;
select dining_test.ok((public.booking_public_config('bc000000-0000-4000-8000-000000000021','https://dining-a.example.test')->'services'->0->>'maxParty')::integer=6,'public config reflects actual table capacities');
select dining_test.ok(public.booking_public_config('bc000000-0000-4000-8000-000000000021','https://dining-a.example.test')->'services'->0->>'resourceId' is null,'public config does not expose tables');
select dining_test.fails($q$select dining_test.book(null,1)$q$,'22023','dining requires party size');
select dining_test.fails($q$select dining_test.book(31,1)$q$,'22023','out-of-range party refused');
select set_config('dining_test.first',(dining_test.book(2,1)->>'id'),true);
select dining_test.ok((select resource_id='bc000000-0000-4000-8000-000000000031' and party_size=2 from public.appointments where id=current_setting('dining_test.first')::uuid),'small party receives smallest fitting table');
select dining_test.ok(dining_test.book(2,1)->>'id'=current_setting('dining_test.first'),'idempotent retry retains reservation');
select dining_test.fails($q$select dining_test.book(3,1)$q$,'23505','changed-party retry refused even with same hash');
select set_config('dining_test.second',(dining_test.book(2,2)->>'id'),true);
select dining_test.ok((select resource_id='bc000000-0000-4000-8000-000000000032' from public.appointments where id=current_setting('dining_test.second')::uuid),'next party uses another fitting table');
select dining_test.fails($q$select dining_test.book(1,4)$q$,'23P01','minimum party rules prevent seating one at the remaining large table');
select set_config('dining_test.large',(dining_test.book(6,3)->>'id'),true);
select dining_test.fails($q$select dining_test.book(6,4)$q$,'23P01','full fitting capacity rejects another party');
select dining_test.ok(not exists(select 1 from jsonb_array_elements(public.booking_public_slots('bc000000-0000-4000-8000-000000000021','https://dining-a.example.test','bc000000-0000-4000-8000-000000000041',current_date+3,6)) t where (t->>'startsAt')::timestamptz=(current_date+3)+time '16:30'),'turnaround prevents immediate reuse');
select set_config('dining_test.request1',(dining_test.book(6,5,18,true)->>'id'),true);
select set_config('dining_test.request2',(dining_test.book(6,6,18,true)->>'id'),true);
reset role;select set_config('request.jwt.claim.role','authenticated',true);set local role authenticated;
select public.manage_booking(current_setting('dining_test.request1')::uuid,'confirm',1);
select dining_test.fails($q$select public.manage_booking(current_setting('dining_test.request2')::uuid,'confirm',1)$q$,'23P01','approval rechecks fitting capacity');
select dining_test.fails($q$select public.manage_booking(current_setting('dining_test.large')::uuid,'reschedule',1,(current_date+3)+time '18:00')$q$,'23P01','unavailable reschedule rejected atomically');
select dining_test.ok((select starts_at=(current_date+3)+time '15:00' and status='confirmed' from public.appointments where id=current_setting('dining_test.large')::uuid),'failed move retains original allocation');
select dining_test.fails($q$select public.save_booking_table('bc000000-0000-4000-8000-000000000021','{"id":"bc000000-0000-4000-8000-000000000033","name":"Six seats","active":true,"minParty":1,"maxParty":4}')$q$,'22023','capacity cannot invalidate upcoming confirmed parties');
reset role;select set_config('request.jwt.claim.role','service_role',true);set local role service_role;
select public.manage_guest_booking('bc000000-0000-4000-8000-000000000021','https://dining-a.example.test',current_setting('dining_test.large')::uuid,repeat('b',64),'cancel');
select dining_test.ok((dining_test.book(6,7)->>'partySize')::integer=6,'cancelled table becomes available with party receipt');
select set_config('dining_test.small_request1',(dining_test.book(2,8,20,true)->>'id'),true);
select set_config('dining_test.small_request2',(dining_test.book(2,9,20,true)->>'id'),true);
reset role;select set_config('request.jwt.claim.role','authenticated',true);set local role authenticated;
select public.manage_booking(current_setting('dining_test.small_request1')::uuid,'confirm',1);
select public.manage_booking(current_setting('dining_test.small_request2')::uuid,'confirm',1);
select dining_test.ok((select count(distinct resource_id)=2 from public.appointments where id in (current_setting('dining_test.small_request1')::uuid,current_setting('dining_test.small_request2')::uuid)),'approval reassigns the second provisional request to another table');
select dining_test.ok(public.block_booking_dining_days('bc000000-0000-4000-8000-000000000021',current_date+4,current_date+4,'Closed for holiday')=3,'business holiday blocks every table atomically');
reset role;select set_config('request.jwt.claim.role','service_role',true);set local role service_role;
select dining_test.ok(public.booking_public_slots('bc000000-0000-4000-8000-000000000021','https://dining-a.example.test','bc000000-0000-4000-8000-000000000041',current_date+4,2)='[]'::jsonb,'closed dining day offers no table slots');
reset role;
select dining_test.fails($q$update public.appointments set party_size=7 where id=current_setting('dining_test.first')::uuid$q$,'23514','database independently validates assigned capacity');
select set_config('request.jwt.claim.role','authenticated',true);select set_config('request.jwt.claim.sub','bc000000-0000-4000-8000-000000000003',true);set local role authenticated;
select dining_test.fails($q$select public.save_booking_dining_hours('bc000000-0000-4000-8000-000000000021','[]')$q$,'42501','members cannot change restaurant hours');
reset role;select set_config('request.jwt.claim.sub','bc000000-0000-4000-8000-000000000002',true);set local role authenticated;
select dining_test.ok((select count(*)=0 from public.appointments),'other tenant sees no party data');
reset role;select set_config('request.jwt.claim.role','anon',true);set local role anon;
select dining_test.fails($q$select public.save_booking_table('bc000000-0000-4000-8000-000000000021','{}')$q$,'42501','anonymous table management refused');
reset role;rollback;
